#!/usr/bin/env node
/**
 * Builds frontend/public/vendor/cb-native.js: the native character drawing (lib/native/character.ts
 * and what it needs) as one browser script for the video renderer's static page
 * (public/render-harness.html), which is plain JavaScript and cannot import the app's modules.
 * It exposes window.CBNative.createNativeCharacter. Run it after changing lib/native or lib/fla;
 * `node build-native-bundle.js --check` fails when the committed bundle is out of date.
 */
const fs = require("fs"), path = require("path");
const root = path.resolve(__dirname, "../../frontend");
const ts = require(path.join(root, "node_modules/typescript"));
const entry = "lib/native/character";
const out = path.join(root, "public/vendor/cb-native.js");

const modules = new Map(); // id (no extension) -> compiled source
function add(id) {
  if (modules.has(id)) return;
  const file = path.join(root, id + ".ts");
  const source = fs.readFileSync(file, "utf8");
  const js = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020, esModuleInterop: false }, fileName: file }).outputText;
  modules.set(id, js);
  for (const match of js.matchAll(/require\("(\.[^"]+)"\)/g)) add(path.posix.normalize(path.posix.join(path.posix.dirname(id), match[1])));
}
add(entry);

let body = "";
for (const [id, js] of modules) {
  const fixed = js.replace(/require\("(\.[^"]+)"\)/g, (_, rel) => `require(${JSON.stringify(path.posix.normalize(path.posix.join(path.posix.dirname(id), rel)))})`);
  body += `defs[${JSON.stringify(id)}] = function (exports, require) {\n${fixed}\n};\n`;
}
const bundle = `/* Generated by tools/native-test/build-native-bundle.js from lib/native and lib/fla. Do not edit. */
(function () {
  var defs = {}, cache = {};
  function require(id) {
    if (cache[id]) return cache[id].exports;
    if (!defs[id]) throw new Error("cb-native: missing module " + id);
    var module = cache[id] = { exports: {} };
    defs[id](module.exports, require);
    return module.exports;
  }
${body}
  window.CBNative = { createNativeCharacter: require(${JSON.stringify(entry)}).createNativeCharacter };
})();
`;
if (process.argv.includes("--check")) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, "utf8") : "";
  if (current !== bundle) { console.error("public/vendor/cb-native.js is out of date: run tools/native-test/build-native-bundle.js"); process.exit(1); }
  console.log("cb-native.js is up to date");
} else {
  fs.writeFileSync(out, bundle);
  console.log(`wrote ${path.relative(process.cwd(), out)} (${(bundle.length / 1024).toFixed(0)} KB, ${modules.size} modules: ${[...modules.keys()].join(", ")})`);
}
